package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * A sheet's dated settings: each key's value in force on a date is the one with the latest from-date on or before it;
 * before every from-date, the key's starting value (see {@link Setting#starting}).
 */
public record DatedSettings(List<DatedValue> values) {

    /** The key's value in force on the date; null when blank. */
    public String on(String key, LocalDate date) {
        DatedValue found = null;
        for (DatedValue v : values) {
            if (v.key().equals(key) && !v.from().isAfter(date) && (found == null || v.from().isAfter(found.from()))) {
                found = v;
            }
        }
        return found == null ? Setting.starting(key) : found.value();
    }

    /** The floor in force on the date: the least a claim's live due may be. */
    public BigDecimal floor(LocalDate date) {
        return new BigDecimal(orStarting(Setting.FLOOR, date)).setScale(2);
    }

    /** The late percent in force on the date. */
    public BigDecimal latePct(LocalDate date) {
        return new BigDecimal(orStarting(Setting.LATE_PCT, date)).setScale(2);
    }

    /** The terms of the grade in force on the date: its own (setting terms-<grade>), else the sheet's. */
    public int terms(String grade, LocalDate date) {
        String value = grade == null ? null : on(Setting.TERMS_OF_GRADE + grade, date);
        return Integer.parseInt(value == null ? orStarting(Setting.TERMS, date) : value);
    }

    /** The clerk limit in force on the date; null when there is none. */
    public BigDecimal clerkLimit(LocalDate date) {
        String value = on(Setting.CLERK_LIMIT, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The cap in force on the date: the most a person's due-total may be; null when there is none. */
    public BigDecimal cap(LocalDate date) {
        String value = on(Setting.CAP, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    private String orStarting(String key, LocalDate date) {
        String value = on(key, date);
        return value == null ? Setting.starting(key) : value;
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * The settings on each sheet, by key; a key without a row is blank. A dated setting (see {@link Setting#isDated}) keeps
 * every value saved, each from its from-date; the one in force on a date is the latest from on or before it (see
 * {@link DatedSettings}).
 */
@Repository
public class SettingRepository {

    private static final RowMapper<Setting> ROW = (rs, n) -> new Setting(rs.getString("sheet_id"),
            rs.getString("setting_key"), rs.getString("setting_value"), null);

    private static final RowMapper<DatedValue> DATED = (rs, n) -> new DatedValue(rs.getString("setting_key"),
            rs.getObject("from_date", LocalDate.class), rs.getString("setting_value"));

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's undated settings, by key (the policy date and period numbering from); a key without a row is not listed. */
    public List<Setting> listUndated(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " ORDER BY setting_key", ROW, sheetId);
    }

    /** The sheet's dated settings: every value recorded, by key and from-date. */
    public DatedSettings dated(String sheetId) {
        return new DatedSettings(jdbc.query("SELECT setting_key, from_date, setting_value FROM sheet_setting_from"
                + " WHERE sheet_id = ? ORDER BY setting_key, from_date", DATED, sheetId));
    }

    /** The undated setting's value; null when blank. */
    public String find(String sheetId, String key) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " AND setting_key = ?", ROW, sheetId, key).stream().findFirst().map(Setting::value).orElse(null);
    }

    /** A person's due-total held to the cap: the cap when it is above it; n/a (null) and no cap leave it as it is. */
    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
        return dueTotal == null || cap == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** The sheet's policy date: the one set, else its today. */
    public LocalDate policyDate(String sheetId, LocalDate today) {
        String value = find(sheetId, Setting.POLICY_DATE);
        return value == null ? today : LocalDate.parse(value);
    }

    /** The sheet's period numbering from-date; null while off. */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, Setting.PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The sheet's late charge as of its today, each claim's late percent the one in force on its date, with its policy date for rounding. */
    public LateCharge lateCharge(String sheetId, LocalDate today) {
        return new LateCharge(today, dated(sheetId), policyDate(sheetId, today));
    }

    /** Set an undated setting's value (null: blank), replacing the one there before. */
    public Setting set(String sheetId, String key, String value) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key)"
                + " VALUES (?, ?, ?)", sheetId, key, value);
        return new Setting(sheetId, key, value, null);
    }

    /** Record a dated setting's value (null: blank) from the date, keeping the others; one already from that date is replaced. */
    public void setFrom(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("MERGE INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)"
                + " KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)", sheetId, key, from, value);
    }

    /** Every setting as of the date: each dated key's value in force then (its starting value, or blank), and the undated ones set. */
    public List<SettingResponse> listOn(String sheetId, LocalDate today) {
        DatedSettings dated = dated(sheetId);
        List<SettingResponse> found = new ArrayList<>();
        java.util.Set<String> keys = new java.util.TreeSet<>(List.of(Setting.FLOOR, Setting.TERMS, Setting.LATE_PCT));
        dated.values().forEach(v -> keys.add(v.key()));
        for (String key : keys) {
            found.add(new SettingResponse(key, dated.on(key, today), dated.values().stream()
                    .filter(v -> v.key().equals(key))
                    .map(v -> new SettingResponse.From(v.from().toString(), v.value())).toList()));
        }
        listUndated(sheetId).forEach(s -> found.add(new SettingResponse(s.key(), s.value(), List.of())));
        return found;
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A setting's fields: a known key, its value, and for a dated setting an optional from-date (yyyy-mm-dd). The terms are a whole number of days. A grade's terms (terms-<grade>) are a whole number of days, or blank for the sheet's terms. The floor is an amount with up to two decimals. The clerk limit is an amount with up to two decimals, or blank for no limit. The late percent is a number with up to two decimals. The policy date is a date (yyyy-mm-dd), or blank for the sheet's today. Period numbering from is a date, or blank for off. The cap is an amount with up to two decimals, or blank for none. */
public class ValidateSetting {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> setting, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String text = request == null || request.value() == null ? "" : request.value().trim();
        String fromText = request == null || request.from() == null ? "" : request.from().trim();
        java.time.LocalDate from = null;
        if (!fromText.isEmpty()) {
            if (!Setting.isDated(key)) {
                throw new BadRequestException("The " + key + " setting is not dated; leave its from-date blank");
            }
            try {
                from = java.time.LocalDate.parse(fromText);
            } catch (java.time.format.DateTimeParseException e) {
                throw new BadRequestException("A from-date is a date (yyyy-mm-dd), or blank for the sheet's today");
            }
        }
        if (Setting.TERMS.equals(key)) {
            if (!DAYS.matcher(text).matches()) {
                throw new BadRequestException("Terms are a whole number of days");
            }
            setting.set(new SettingInput(key, String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.TERMS_OF_GRADE) && Setting.GRADES.contains(key.substring(Setting.TERMS_OF_GRADE.length()))) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("A grade's terms are a whole number of days, or blank for the sheet's terms");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.FLOOR.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A floor is an amount with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.LATE_PCT.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A late percent is a number with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.POLICY_DATE.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("A policy date is a date (yyyy-mm-dd), or blank for the sheet's today");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PERIOD_NUMBERING_FROM.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("Period numbering from is a date (yyyy-mm-dd), or blank for off");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.CAP.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A cap is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (!Setting.CLERK_LIMIT.equals(key)) {
            throw new BadRequestException("No such setting: " + key);
        }
        String value = null;
        if (!text.isEmpty()) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A clerk limit is an amount with up to two decimals, or blank for no limit");
            }
            value = new BigDecimal(text).setScale(2).toPlainString();
        }
        setting.set(new SettingInput(key, value, from));
        changedBy.set(by);
    }
}
